# -*- coding: utf-8 -*-
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "vq"))
from figs import flow, layers, columns, reg, ALL
ALL.clear()
def F(n, f): reg("ct-%s.svg" % n, f)
F("1-1", lambda: flow("Four ways memory fails", "What goes wrong with piles of notes and AI memory.", [("Islands", "fields never meet", "r"), ("Decay", "gaps pile up", "a"), ("Conflict", "old and new both served", "r"), ("Lock-in", "tied to one model", "a")], "CTMV is a design that answers each one.", per=4))
F("1-2", lambda: columns("Archive or engine?", "Search alone only stores.", [("search", "finds similar words"), ("store", "keeps what you give it")], [("bridges", "finds shared ideas"), ("garden", "spots gaps and conflicts"), ("explain", "shows its proof")], "Passive archive", "Active engine", "The goal is to turn the first into the second."))
F("2-1", lambda: layers("One vault, three modalities", "The same notes seen three ways.", [("V  Vault", "markdown files: the truth", "g"), ("G  Graph", "facts and rules: the logic", "b"), ("M  Manifold", "vectors: the geometry", "v")], "G and M are built from V and can be thrown away."))
F("2-2", lambda: columns("What each view is good at", "Each covers the others' gaps.", [("V", "readable, portable, yours"), ("G", "exact, provable, explainable")], [("M", "fuzzy, fast, finds neighbours"), ("together", "logic plus feel")], "Reads and reasons", "Feels and finds", "None of them is enough alone."))
F("3-1", lambda: flow("Anatomy of a note", "A note is plain text with a little structure.", [("# heading", "the title", "b"), ("tags:", "the area", "g"), ("prose", "sentences", "a"), ("- a causes b", "claim lines", "v"), ("[[other]]", "links", "p")], "Claim lines are what the extractor reads.", per=5))
F("3-2", lambda: flow("A safe write", "Never leave a half-written note.", [("write temp file", "new text", "v"), ("rename over note", "one step", "g"), ("rebuild G and M", "from the file", "b"), ("nothing half-done", "even if power fails", "a")], "Write then rename is atomic.", per=4))
F("4-1", lambda: flow("From sentence to proof", "How a claim becomes an answer.", [("claim line", "retry_storm causes overload", "v"), ("fact", "claim(note, a, causes, b)", "b"), ("rule", "leads_to chains causes", "a"), ("answer", "with its proof", "g")], "Every answer names the facts it rests on.", per=4))
F("4-2", lambda: columns("Three verdicts", "The engine never bluffs.", [("proven", "facts and rules show it"), ("contradicted", "the opposite holds or a rule breaks")], [("unknown", "nothing says either way"), ("open world", "missing is not false")], "Sure", "Not sure", "Unknown is an honest answer."))
F("5-1", lambda: flow("From text to a point", "What the toy embedder does.", [("note text", "title, prose, claims", "b"), ("tokens", "words and word parts", "g"), ("hash", "into 64 slots", "a"), ("unit vector", "length one", "v"), ("vec0 row", "in sqlite-vec", "p")], "A real model replaces the middle steps.", per=5))
F("5-2", lambda: columns("Toy or real embedder", "Same shape, different quality.", [("hashing (labs)", "offline, same every time, crude")], [("model (real use)", "captures meaning; can be swapped")], "In the labs", "In real use", "Swapping the model changes M only."))
F("6-1", lambda: flow("The commuting square", "Two routes from a note to the manifold.", [("note in V", "", "b"), ("pi: extract", "facts in G", "g"), ("f: warp, anchor", "geometry from logic", "a"), ("point in M", "", "v")], "phi (embed) goes straight from V to M. The square commutes if both routes meet.", per=4))
F("6-2", lambda: columns("Reading delta", "How far apart the two routes land.", [("delta near 0", "wording and logic agree")], [("delta high", "bridge, false friend or missing fact")], "Agree", "Disagree", "A large delta is a clue, not an error."))
F("7-1", lambda: flow("Finding a bridge", "Two notes, one pattern.", [("far apart in M", "different words", "b"), ("share an idea in G", "same loop", "g"), ("no link in V", "never connected", "a"), ("bridge candidate", "you decide", "v")], "The engine suggests; you judge.", per=4))
F("7-2", lambda: columns("Bridge or false friend", "Two ways the views disagree.", [("far in M, shared in G", "same pattern, other words")], [("near in M, nothing shared", "similar words, other meaning")], "Bridge", "False friend", "Both are worth a look."))
F("8-1", lambda: layers("The gardening checklist", "What a gardener looks for.", [("Contradictions", "a constraint breaks", "r"), ("Latent syntheses", "shared idea, no link", "b"), ("Gaps", "an idea with no note", "a"), ("Orphans", "notes no one links", "v")], "Run it on a schedule or on demand."))
F("8-2", lambda: flow("Suggest, do not rewrite", "The gardener never edits your notes.", [("finds", "a pattern", "b"), ("writes", "a suggestion", "g"), ("you review", "accept or reject", "a"), ("remembered", "rejected stays rejected", "v")], "Your notes stay yours.", per=4))
F("9-1", lambda: flow("Warping the distance", "Change how far apart notes seem.", [("start", "distance d", "b"), ("cause link", "d times (1 minus lambda)", "g"), ("conflict", "d plus mu", "r"), ("rank by", "the warped distance", "v")], "Vectors stay put; only the ruler changes.", per=4))
F("9-2", lambda: columns("Pull and push", "Two dials.", [("lambda: pull", "causes come closer")], [("mu: push", "conflicts move apart")], "Closer", "Further", "Zero means plain search."))
F("10-1", lambda: flow("Multi-hop retrieval", "Follow the chain, not just the neighbours.", [("query", "your question", "b"), ("nearest note", "the seed", "g"), ("hop", "along warped edges", "a"), ("reach", "stop at the budget", "v"), ("drop replaced", "flag disputes", "r")], "Each result can name why it was returned.", per=5))
F("10-2", lambda: columns("Plain or warped", "What changes in the answer.", [("plain k-NN", "similar text, old or new")], [("warped", "adds causes, drops replaced, flags disputes")], "Plain", "Warped", "Fewer confident mistakes."))
F("11-1", lambda: flow("Replay", "Rebuild everything from the files.", [("markdown files", "the truth", "g"), ("discard G and M", "they are caches", "r"), ("extract and embed", "pi and phi", "b"), ("same facts", "new geometry", "v")], "A new model changes M and nothing else.", per=4))
F("11-2", lambda: layers("What is precious", "Back up the right thing.", [("V  Vault", "keep and back up", "g"), ("G  Graph", "rebuild any time", "b"), ("M  Manifold", "rebuild when the model changes", "a")], "Plain files outlive every tool."))
F("12-1", lambda: layers("The Jade stack", "Parts that already exist.", [("jade-agent-kit file system", "markdown notes", "g"), ("jade-kg", "Datalog with proofs", "b"), ("SQLite + sqlite-vec", "vectors and FTS5", "v"), ("Ollama embeddings", "real meaning, when online", "a")], "The labs use all but the last."))
F("12-2", lambda: flow("A plan to test it", "Do not trust, measure.", [("build it", "on the Jade stack", "b"), ("test vault", "known bridges and conflicts", "g"), ("measure", "found, caught, missed", "a"), ("compare", "with plain search", "v")], "A design is not a result.", per=4))
